package com.magdi.tube;
import android.content.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35,application=android.app.Application.class)
public class SharedSupportIdentityTest {
 @Test public void persistentRandomIdentityDoesNotRewriteInstallationOrConsent(){Context c=RuntimeEnvironment.getApplication();SharedPreferences app=c.getSharedPreferences("mm_support_v1",0);app.edit().putString("id","legacy").putString("token","private").putBoolean("enabled",false).commit();SharedSupportIdentity.Identity first=SharedSupportIdentity.owned(c);assertTrue(SharedSupportIdentity.valid(first.id,first.secret));assertEquals(first.id,SharedSupportIdentity.owned(c).id);assertEquals(first.secret,SharedSupportIdentity.owned(c).secret);assertEquals("legacy",app.getString("id",""));assertEquals("private",app.getString("token",""));assertFalse(app.getBoolean("enabled",false));}
 @Test public void concurrentFirstUseReturnsOneIdentity() throws Exception {Context c=RuntimeEnvironment.getApplication();java.util.Set<String> ids=java.util.Collections.synchronizedSet(new java.util.HashSet<>());java.util.List<Thread> threads=new java.util.ArrayList<>();for(int i=0;i<8;i++){Thread t=new Thread(()->ids.add(SharedSupportIdentity.owned(c).id));threads.add(t);t.start();}for(Thread t:threads)t.join();assertEquals(1,ids.size());}
 @Test public void untrustedAndUnsignedPackagesCannotSupplyIdentity(){Context c=RuntimeEnvironment.getApplication();assertFalse(SharedSupportIdentity.trusted(c.getPackageManager(),"com.attacker"));assertFalse(SharedSupportIdentity.trusted(c.getPackageManager(),"com.magdi.auto"));assertFalse(SharedSupportIdentity.valid("123","abc"));}
 @Test public void absentBrokerPreservesCachedIdentity(){Context c=RuntimeEnvironment.getApplication();SharedSupportIdentity.Identity cached=SharedSupportIdentity.owned(c);assertEquals(cached.id,SharedSupportIdentity.resolve(c).id);assertEquals(cached.secret,SharedSupportIdentity.resolve(c).secret);}
}
